51	std::string number_text(double value)
52	{
53	    std::ostringstream out;
54	    out.precision(2);
55	    out << std::fixed << value;
56	    std::string text = out.str();
57	    while (text.size() > 3 && text.back() == '0')
58	        text.pop_back();
59	    return text;
60	}
