63	std::string sizes_text(const std::vector<double>& nozzles)
64	{
65	    std::string text;
66	    for (std::size_t i = 0; i < nozzles.size(); ++i)
67	        text += (i == 0 ? "" : i + 1 == nozzles.size() ? " and " : ", ") + number_text(nozzles[i]);
68	    return text + " mm";
