197	void PrinterConversation::show_plugin_needed(const std::string& message_id)
198	{
199	    m_needs_plugin = true;
200	    const bool shown = std::any_of(m_blocks.begin(), m_blocks.end(), [](const json& block) {
201	        return block.value("kind", std::string()) == "plugin" && !block.value("installed", false);
202	    });
203	    if (shown)
204	        return;
205	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id}, {"kind", "plugin"}});
206	    m_host.session_changed();
207	}
