209	void PrinterConversation::install_network_plugin()
210	{
211	    if (!m_needs_plugin || m_printer_name.empty())
212	        return;
213	    m_backend.install_network_plugin();
214	    // Closing the installer, or a download that failed, leaves the notice
215	    // and its button as they were; Orca's dialog has said what happened.
216	    if (m_backend.connection(m_printer_name).needs_network_plugin)
217	        return;
218	    m_needs_plugin = false;
219	    for (json& block : m_blocks)
220	        if (block.value("kind", std::string()) == "plugin")
221	            block["installed"] = true;
222	    // Discovery could not start without the plug-in; the next status check
223	    // starts it.
224	    m_prepared.clear();
225	    m_host.post_note("Bambu's network plug-in is installed now, so " + m_printer_name + " can be connected.");
226	    m_host.session_changed();
227	    m_host.start_turn();
228	}
