261	json PrinterConversation::context_json() const
262	{
263	    json context = json::object();
264	    if (m_mode == ConversationMode::Add) {
265	        json printers = json::array();
266	        for (const CatalogPrinter& printer : m_backend.catalog())
267	            printers.push_back(json::array({printer.id, printer.display_name(), printer.build_volume}));
268	        json network = json::array();
269	        for (const DiscoveredPrinter& found : m_network)
270	            network.push_back(json{{"name", found.name}, {"serial", found.stable_id}});
271	        context["printers"] = std::move(printers);
272	        context["network"]  = std::move(network);
273	    }
274	    if (const SavedPrinter printer = about(); !printer.name.empty()) {
275	        context["printer"]             = printer_json(printer);
276	        context["printer"]["provider"] = printer.vendor_id == "BBL" ? "bambu" : "host";
277	        if (printer.stock) {
278	            context["printer"]["stock"]    = true;
279	            context["printer"]["copyName"] = printer.copy_name;
280	        }
281	        if (m_needs_plugin)
282	            context["printer"]["needsNetworkPlugin"] = true;
283	    }
284	    return context;
285	}
