287	Agent::AgentSessionProfile PrinterConversation::profile() const
288	{
289	    Agent::AgentSessionProfile profile;
290	    // The tools are the app's to decide; the words are the page's
291	    // (printerInstructions.ts), sent with printer_instructions.
292	    profile.tool_names = session_tools();
293	    const std::vector<std::string> settings = settings_tools();
294	    profile.tool_names.insert(profile.tool_names.end(), settings.begin(), settings.end());
295	    profile.instructions = m_instructions;
296	    // This conversation is about a machine, not about the open project, and
297	    // what the app does on its own reaches the model as notes.
298	    profile.include_workspace          = false;
299	    return profile;
