435	void PrinterConversation::tool_settled(const ToolActivity& activity)
436	{
437	    if (activity.tool != "settings_apply_patch" || activity.state != Agent::ToolState::Succeeded)
438	        return;
439	    const std::string saved_as = json::parse(activity.result_json).value("savedAs", std::string());
440	    if (saved_as.empty() || saved_as == m_printer_name)
441	        return;
442	    // Saved as a copy, which Orca selected in the preset's place: the
443	    // printer the person now has, and Home lists it.
444	    m_printer_name = saved_as;
445	    m_host.printers_changed(saved_as);
446	    m_host.session_changed();
447	}
