557	Result PrinterConversation::connection_status(const std::string& name, const std::string& message_id)
558	{
559	    if (saved(name).name.empty())
560	        return refuse("no_printer", "There is no saved printer to connect yet: add one first.");
561	    // For a Bambu Lab printer this starts looking for it on the network --
562	    // once: starting again switches the printer agent and restarts discovery,
563	    // so a model that checks again would never let it find anything.
564	    if (m_prepared != name) {
565	        m_backend.prepare_connection(name);
566	        m_prepared = name;
567	    }
568	    const PrinterConnectionInfo info = m_backend.connection(name);
569	    if (info.needs_network_plugin)
570	        show_plugin_needed(message_id);
571	    return ok(connection_json(info));
572	}
