583	void PrinterConversation::connect(const json& arguments, const std::string& credential)
584	{
585	    const std::string name   = arguments.at("printerName");
586	    const std::string target = arguments.at("target");
587	    const std::string problem =
588	        arguments.at("provider") == "bambu" ?
589	            m_backend.connect_printer(name, arguments.at("deviceId"), credential) :
590	            m_backend.connect_host(name, arguments.at("hostType"), arguments.at("address"), credential);
591	    if (!problem.empty()) {
592	        m_host.post_note("Connection to " + target + " failed: " + problem);
593	        m_host.session_changed();
594	        m_host.start_turn();
595	        return;
596	    }
597	    m_connecting = name;
598	    m_last_look  = {};
599	    m_host.session_changed();
600	}
