610	void PrinterConversation::tick(std::chrono::steady_clock::time_point now)
611	{
612	    if (m_form && m_form->reading.valid() && m_form->reading.wait_for(std::chrono::seconds(0)) == std::future_status::ready) {
613	        m_form->options = m_form->reading.get();
614	        m_host.session_changed();
615	    }
616	    if (m_connecting.empty() || now - m_last_look < kConnectionLook)
617	        return;
618	    m_last_look = now;
619	    const PrinterConnectionInfo info = m_backend.connection(m_connecting);
620	    if (info.state == "connecting")
621	        return;
622	    const std::string name = m_connecting;
623	    m_connecting.clear();
624	    m_host.post_note(info.state == "verified" ? "Connection to " + name + " verified." :
625	                                                "Connection to " + name + " failed: " + info.message);
626	    m_host.printers_changed();
627	    m_host.session_changed();
628	    m_host.start_turn();
629	}
