631	// -- The panel's own page --------------------------------------------------
632	
633	bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
634	{
635	    if (type == "printer_instructions") {
636	        // Bounded: the page's words become every request's system prompt.
637	        const std::string text = payload.value("text", std::string());
638	        if (text.size() <= kInstructionsLimit && text != m_instructions) {
639	            m_instructions = text;
640	            m_host.profile_changed();
641	        }
642	        return true;
643	    }
644	    if (type == "printer_opening") {
645	        // The first line is the page's to write and the app's to post, once:
646	        // a reloaded page asks again, and the thread already has it.
647	        const std::string text = payload.value("text", std::string());
648	        if (m_opened || text.empty() || text.size() > kNoteLimit)
649	            return true;
650	        m_opened                     = true;
651	        const std::string message_id = m_host.post_opening(text);
652	        for (json& entry : m_blocks)
653	            if (entry.value("afterMessageId", std::string()).empty())
654	                entry["afterMessageId"] = message_id;
655	        m_host.session_changed();
656	        return true;
657	    }
658	    if (type != "printer_action")
659	        return false;
660	
661	    const std::string action = payload.value("action", std::string());
662	    if (action == "close")
663	        m_host.close_panel();
664	    else if (action == "manual_setup")
665	        open_form();
666	    else if (action == "form_options")
667	        ask_form_options(payload);
668	    else if (action == "form_finish")
669	        finish_form(payload);
670	    else if (action == "form_close") {
671	        m_form.reset();
672	        m_host.session_changed();
673	    } else if (action == "orca_printer_list") {
674	        // OrcaSlicer's own printer list, for a panel whose page could not
675	        // load and so cannot show the form; what it added is news the model
676	        // answers.
677	        const ManualPrinterResult result = m_backend.run_manual_setup();
678	        if (!result.added.empty()) {
679	            m_printer_name = result.added.front().name;
680	            m_host.post_note("The person added " + m_printer_name + " from the printer list.");
681	            m_host.printers_changed(m_printer_name);
682	            m_host.session_changed();
683	            m_host.start_turn();
684	        }
685	    } else if (action == "connect" && payload.value("actionId", std::string()) == m_credential_action &&
686	               payload.contains("credential") && payload["credential"].is_string()) {
687	        const json arguments = std::move(m_credential_arguments);
688	        m_credential_action.clear();
689	        m_credential_arguments = json::object();
690	        connect(arguments, payload["credential"].get<std::string>());
691	    } else if (action == "open_printer_settings" && !m_printer_name.empty()) {
692	        m_backend.open_printer_settings(m_printer_name);
693	        m_host.printers_changed();
694	        m_host.session_changed();
695	    } else if (action == "undo_add")
696	        undo_add(payload.value("blockId", std::string()));
697	    else if (action == "install_network_plugin")
698	        install_network_plugin();
699	    return true;
700	}
701	
702	void PrinterConversation::undo_add(const std::string& block_id)
703	{
704	    json* receipt = nullptr;
705	    for (json& block : m_blocks)
706	        if (block.value("id", std::string()) == block_id && block.value("kind", std::string()) == "added")
707	            receipt = &block;
708	    // A second tap that arrived before the page redrew the first has nothing
709	    // left to undo.
710	    if (receipt == nullptr || receipt->value("removed", false))
711	        return;
712	
713	    // Orca's own delete, as Home's "Remove printer…" runs it: the printer the
714	    // project was set up for gives way to the profile it was based on.
715	    const std::string name = receipt->at("printer").at("name");
716	    if (const std::string problem = m_backend.remove_printer(name); !problem.empty()) {
717	        m_host.post_note("Undo did not remove " + name + ": " + problem);
718	        m_host.session_changed();
719	        return;
720	    }
721	    // printer_add saves a printer based on a shipped profile, which Orca
722	    // deletes without asking; only a printer of the person's own design can
723	    // be kept by declining there.
724	    if (!saved(name).name.empty())
725	        throw std::logic_error("Removing an added printer left it saved");
726	
727	    if (m_connecting == name)
728	        abandon_connection();
729	    (*receipt)["removed"] = true;
730	    // The same printer can now be added again, and nothing here is about it.
731	    for (auto added = m_added.begin(); added != m_added.end();)
732	        added = added->second == name ? m_added.erase(added) : std::next(added);
733	    if (m_printer_name == name)
734	        m_printer_name.clear();
735	    if (m_prepared == name)
736	        m_prepared.clear();
737	    m_host.post_note("The person tapped Undo on the receipt: " + name + " is removed and is no longer one of their printers.");
738	    m_host.printers_changed();
739	    m_host.session_changed();
740	    m_host.start_turn();
741	}
