902	json PrinterConversation::form_json() const
903	{
904	    json catalog = json::array();
905	    for (const CatalogPrinter& printer : m_backend.catalog())
906	        catalog.push_back(json{{"id", printer.id},
907	                               {"vendorId", printer.vendor_id},
908	                               {"brand", printer.vendor_name},
909	                               {"model", printer.model_name},
910	                               {"nozzles", printer.nozzles}});
911	    json nearby = json::array();
912	    for (const auto& [found, model] : m_form->nearby)
913	        nearby.push_back(json{{"deviceId", found.stable_id}, {"name", found.name}, {"catalogId", model}});
914	    json form{{"catalog", std::move(catalog)}, {"nearby", std::move(nearby)}, {"error", m_form->error},
915	              {"loading", m_form->reading.valid()}};
916	    if (const auto& options = m_form->options) {
917	        json plates = json::array();
918	        for (const PlateOption& plate : options->plates)
919	            plates.push_back(json{{"type", plate.type}, {"label", plate.label}});
920	        const auto list = [](const std::vector<FilamentOption>& filaments) {
921	            json entries = json::array();
922	            for (const FilamentOption& filament : filaments) {
923	                json entry{{"name", filament.name}, {"label", filament.label}, {"vendor", filament.vendor}, {"material", filament.material}};
924	                if (!filament.made_for.empty())
925	                    entry["madeFor"] = filament.made_for;
926	                if (!filament.base.empty())
927	                    entry["base"] = filament.base;
928	                entries.push_back(std::move(entry));
929	            }
930	            return entries;
931	        };
932	        form["options"] = json{{"catalogId", options->catalog_id},
933	                               {"nozzle", options->nozzle},
934	                               {"plates", std::move(plates)},
935	                               {"defaultPlate", options->default_plate},
936	                               {"filaments", list(options->filaments)},
937	                               {"others", list(options->others)},
938	                               {"own", list(options->own)},
939	                               {"suggested", options->suggested},
940	                               {"defaultFilament", options->default_filament},
941	                               {"error", options->error}};
942	    }
943	    return form;
944	}
