372	PrinterConnectionInfo OrcaPrinterBackend::connection(const std::string& name)
373	{
374	    PrinterConnectionInfo info;
375	    const auto saved = saved_printers();
376	    const auto printer = std::find_if(saved.begin(), saved.end(), [&](const SavedPrinter& p) { return p.name == name; });
377	    if (printer == saved.end()) {
378	        info.state = "unavailable";
379	        info.message = "This printer was renamed or removed. Open it again from Printers.";
380	        return info;
381	    }
382	    const CatalogPrinter* model = model_of(name);
383	    if (!model || model->vendor_id != "BBL") {
384	        const Preset* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
385	        if (!preset)
386	            throw std::logic_error("A saved printer has no preset");
387	        if (m_host_attempt && m_host_attempt->name == name && m_host_attempt->state == "connecting")
388	            settle(*m_host_attempt);
389	        const auto type = preset->config.opt_enum<PrintHostType>("host_type");
390	        info.address = preset->config.opt_string("print_host");
391	        info.host_type = type == htMoonraker ? "moonraker" : type == htOctoPrint ? "octoprint" : "other";
392	        info.provider = "host";
393	        info.state = info.address.empty() ? "not_configured" : "unknown";
394	        if (info.state == "unknown")
395	            info.message = "A connection is saved. Test it to check access; live printer status is not available here.";
396	        if (info.host_type == "other") {
397	            info.state = "unavailable";
398	            info.message = "Configure this connection type in Printer settings. You can still prepare prints and export a file.";
399	        }
400	        if (m_host_attempt && m_host_attempt->name == name) {
401	            auto& attempt = *m_host_attempt;
402	            // Only a verified attempt saved its settings; it holds while the
403	            // printer is still set up as it was tested.
404	            if (attempt.state == "verified" &&
405	                (info.address != attempt.address || info.host_type != attempt.host_type ||
406	                 preset->config.opt_string("printhost_apikey") != attempt.api_key)) {
407	                info.message = "Connection settings changed. Test the new connection again.";
408	                return info;
409	            }
410	            info.state = attempt.state;
411	            info.message = attempt.message;
412	        }
413	        return info;
414	    }
415	    info.provider = "bambu";
416	    info.device_id = printer->device_id;
417	    auto* devices = wxGetApp().getDeviceManager();
418	    auto* agent = wxGetApp().getAgent();
419	    info.signed_in = agent && agent->is_user_login(BBL_CLOUD_PROVIDER);
420	    if (fake_bambu_printer_agent_id(wxGetApp().app_config).empty() && !NetworkAgent::is_network_module_loaded()) {
421	        info.state = "unavailable";
422	        info.needs_network_plugin = true;
423	        info.message = "Connecting a Bambu Lab printer needs Bambu's network plug-in, which is not installed or not turned on. "
424	                       "The printer can already prepare prints without it.";
425	        return info;
426	    }
427	    if (!devices || !agent) {
428	        info.state = "unavailable";
429	        info.message = "Connecting is not available right now. The printer can already prepare prints.";
430	        return info;
431	    }
432	    auto candidates = devices->get_local_machinelist();
433	    for (const auto& entry : devices->get_my_cloud_machine_list())
434	        candidates[entry.first] = entry.second;
435	    for (const auto& [id, machine] : candidates) {
436	        if (!machine || machine->printer_type != model->device_model_id)
437	            continue;
438	        if (!info.device_id.empty() && id != info.device_id)
439	            continue;
440	        const bool used_elsewhere = std::any_of(saved.begin(), saved.end(), [&](const SavedPrinter& p) {
441	            return p.name != name && p.device_id == id;
442	        });
443	        if (!used_elsewhere && (!machine->is_lan_mode_printer() || machine->is_avaliable()))
444	            info.candidates.push_back({id, machine->get_dev_name(), machine->get_dev_ip(), machine->is_lan_mode_printer()});
445	    }
446	    MachineObject* machine = info.device_id.empty() ? nullptr : devices->get_my_machine(info.device_id);
447	    // is_connected() alone is optimistic immediately after reset(). Require
448	    // actual parsed push data, and fresh LAN data for a LAN connection.
449	    const bool communicating = machine && has_recent_printer_data(*machine);
450	    const bool configured = has_verified_printer_connection(info.device_id);
451	    info.state = communicating ? "verified" : configured ? "unknown" : "not_configured";
452	    if (info.state == "unknown")
453	        info.message = "Connection status is unknown. Check that the printer is on, then reconnect.";
454	    if (m_connection_attempt && m_connection_attempt->name == name) {
455	        const auto& attempt = *m_connection_attempt;
456	        if (info.device_id != attempt.device_id)
457	            throw std::logic_error("A connection attempt lost its saved printer association");
458	        const bool observed = communicating &&
459	            (machine->is_lan_mode_printer() ? machine->last_lan_msg_time_ > attempt.observation_start
460	                                           : machine->last_cloud_msg_time_ > attempt.observation_start);
461	        if (devices->get_selected_machine() != machine && machine != nullptr && !attempt.reselecting) {
462	            info.state = "failed";
463	            info.message = "The selected printer changed. Select this printer again to reconnect.";
464	        } else if (observed) {
465	            info.state = "verified";
466	            m_connection_attempt.reset();
467	        } else if (machine == nullptr) {
468	            info.state = "failed";
469	            info.message = "The printer is no longer available. Refresh the printer list and try again.";
470	        } else if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
471	            info.state = "failed";
472	            info.message = "The printer did not respond. Check that it is on the network and try again.";
473	        } else {
474	            info.state = "connecting";
475	            info.message.clear();
476	        }
477	    }
478	    if (info.state == "verified")
479	        wxGetApp().app_config->set("jusprin_verified_connections", info.device_id, "true");
480	    if (communicating) {
481	        const auto* extruders = machine->GetExtderSystem();
482	        info.nozzle_mismatch = extruders && extruders->GetNozzleDiameter(0) > 0 &&
483	            std::abs(extruders->GetNozzleDiameter(0) - printer->nozzle) > 0.001;
484	    }
485	    return info;
486	}
